final class Entitlements {
 use SubscriptionLifecycle;
 public const FEATURES=['menu','inventory','recipes','floor','reservations','pos','kitchen','analytics','billing','branding','multi_outlet','staff'];
 public const FEATURE_DEPENDENCIES=['branding'=>['menu'],'recipes'=>['inventory','menu'],'reservations'=>['floor'],'pos'=>['menu','kitchen','floor']];
 public const LIMITS=['outlets'=>100,'products'=>100000,'staff'=>10000,'tables'=>10000];
 public function __construct(private PDO $db,private AuthenticatedUserProvider $auth,private ?\Closure $clock=null){}
 private function now():int{return $this->clock?($this->clock)():time();}
 public static function enabled():bool{return Environment::get('KIOS_ENTITLEMENTS_ENABLED','0')==='1';}
 private function rows(string $sql,array $p=[]):array{$q=$this->db->prepare($sql);$q->execute($p);return $q->fetchAll(PDO::FETCH_ASSOC);}
 private function admin():string{(new AuthorizationService($this->auth,new PdoIdentityStore($this->db)))->requirePlatformAdministration();$id=$this->auth->currentUserId();if(!$id)throw new DomainException('Platform administrator required.');return $id;}
 private function write(callable $fn):mixed{
  if(!self::enabled()||Environment::get('APP_ENV')!=='demo')throw new DomainException('Private plan management disabled.');if($this->db->inTransaction())throw new \LogicException('Plan manager owns transaction.');
  for($attempt=1;$attempt<=3;$attempt++){$actor=$this->admin();$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
   if($this->auth->currentUserId()!==$actor||!$this->rows("SELECT p.user_id FROM merchant_platform_memberships p JOIN merchant_staff s ON s.user_id=p.user_id AND s.active=1 JOIN merchant_role_permissions r ON r.role_code=p.role_code AND r.permission_code='manage_platform' WHERE p.user_id=? AND p.active=1 FOR UPDATE",[$actor]))throw new DomainException('Current platform authority required.');$r=$fn($actor);$this->db->commit();return $r;
  }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof \PDOException&&in_array((int)($e->errorInfo[1]??0),[1213,1205],true)&&$attempt<3){usleep($attempt*20000);continue;}throw $e;}}
