 private static function text(string $s,int $max):string{if(trim($s)===''||mb_strlen($s)>$max||!mb_check_encoding($s,'UTF-8')||preg_match('/[<>\x00-\x1f\x7f]/u',$s))throw new InvalidArgumentException('Use bounded plain text.');return trim($s);}
 public static function instant(string $s):int{$d=\DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$s,new \DateTimeZone('UTC'));if(!$d||$d->format('Y-m-d\TH:i')!==$s)throw new InvalidArgumentException('Use an exact UTC date and time.');return $d->getTimestamp();}
 private static function request(string $id):void{if(!preg_match('/^[a-f0-9]{32}$/D',$id))throw new InvalidArgumentException('Reload request form.');}
 public function plan(string $request,string $id,string $version,string $name,string $description,array $features,array $limits,string $active,string $metadata=''):array{
  self::request($request);if(!preg_match('/^[a-z][a-z0-9_-]{0,31}$/D',$id)||!ctype_digit($version)||strlen($version)>8||!in_array($active,['0','1'],true)||!array_is_list($features)||array_diff($features,self::FEATURES)||count(array_unique($features))!==count($features))throw new InvalidArgumentException('Invalid plan fields.');foreach(self::FEATURE_DEPENDENCIES as$f=>$deps)if(in_array($f,$features,true)&&array_diff($deps,$features))throw new InvalidArgumentException('Include the prerequisite modules for '.$f);$name=self::text($name,100);$description=self::text($description,500);if(array_diff(array_keys($limits),array_keys(self::LIMITS))||array_diff(array_keys(self::LIMITS),array_keys($limits)))throw new InvalidArgumentException('Supply all supported limits.');foreach($limits as$k=>$v)$limits[$k]=BillDrafts::number($v,0,self::LIMITS[$k]);$metadata=$metadata===''?null:BillDrafts::number($metadata,0,100000000);sort($features);ksort($limits);$hash=hash('sha256',json_encode([$id,$version,$name,$description,$features,$limits,$active,$metadata],JSON_THROW_ON_ERROR));
  return $this->write(function($actor)use($request,$id,$version,$name,$description,$features,$limits,$active,$metadata,$hash){$prior=$this->rows('SELECT * FROM merchant_plan_versions WHERE request_id=? FOR UPDATE',[$request]);if($prior){$p=$prior[0];if($p['actor_id']!==$actor||!hash_equals($p['payload_hash'],$hash))throw new DomainException('Request key conflict.');return ['plan'=>$p['plan_id'],'version'=>(int)$p['version']];}$last=$this->rows('SELECT version FROM merchant_plan_versions WHERE plan_id=? ORDER BY version DESC LIMIT 1 FOR UPDATE',[$id]);if((string)($last[0]['version']??0)!==$version)throw new DomainException('Plan changed; reload current version.');$v=(int)$version+1;$this->rows('INSERT INTO merchant_plan_versions VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$v,$name,$description,$active,json_encode($features),json_encode($limits),$metadata,$actor,$request,$hash,$this->now()]);return ['plan'=>$id,'version'=>$v];});
 }
 private function scopedIdentity(string $m,string $o):void{
  Identity::validate($m);Identity::validate($o);
  if(!$this->db->inTransaction()){TenantContext::resolve($this->auth,new PdoIdentityStore($this->db),$m,$o);return;}
  // Do not reuse the directory's caller-owned snapshot. Revalidate native identity and current locked rows.
  $u=$this->auth->currentUserId();if($u===null)throw new DomainException('Native staff authentication required.');
  if(!$this->rows('SELECT o.outlet_id FROM merchant_outlets o JOIN merchant_organizations m ON m.merchant_id=o.merchant_id AND m.active=1 JOIN merchant_staff s ON s.user_id=? AND s.active=1 WHERE o.merchant_id=? AND o.outlet_id=? AND o.active=1 FOR UPDATE',[$u,$m,$o]))throw new DomainException('Current tenant scope required.');
  $owner=$this->rows("SELECT user_id FROM merchant_memberships WHERE user_id=? AND merchant_id=? AND role_code='merchant_owner' AND active=1 FOR UPDATE",[$u,$m]);$assigned=$this->rows("SELECT user_id FROM merchant_outlet_memberships WHERE user_id=? AND merchant_id=? AND outlet_id=? AND active=1 FOR UPDATE",[$u,$m,$o]);if(!$owner&&!$assigned)throw new DomainException('Current outlet membership required.');
 }
 private function rawAssignment(string $m,bool $lock=false):?array{
  $suffix=$lock?' FOR UPDATE':'';$head=$this->rows('SELECT version FROM merchant_plan_heads WHERE merchant_id=?'.$suffix,[$m]);if(!$head)return null;
  $r=$this->rows('SELECT a.*,p.name,p.description,p.features_json,p.limits_json,p.metadata_paise FROM merchant_plan_assignments a JOIN merchant_plan_versions p ON p.plan_id=a.plan_id AND p.version=a.plan_version WHERE a.merchant_id=? AND a.effective_epoch<=? ORDER BY a.version DESC LIMIT 1'.$suffix,[$m,$this->now()]);return $r[0]??null;
 }
 private function assignment(string $m,bool $lock=false):?array{
  $managed=$this->managedState($m,$lock);return $managed?$managed['assignment']:$this->rawAssignment($m,$lock);
 }
 public function assign(string $request,string $m,string $expected,string $plan,string $pv,string $effective,string $expires,string $reason):array{
  self::request($request);Identity::validate($m);if(!ctype_digit($expected)||strlen($expected)>8||!ctype_digit($pv)||strlen($pv)>8)throw new InvalidArgumentException('Invalid versions.');$start=self::instant($effective);$end=self::instant($expires);$reason=self::text($reason,240);if($end<=$start||$end<=$this->now()||$end-$start>5*366*86400)throw new InvalidArgumentException('Use a future expiry after the effective time within five years.');$hash=hash('sha256',json_encode([$m,$expected,$plan,$pv,$start,$end,$reason]));
  return $this->write(function($actor)use($request,$m,$expected,$plan,$pv,$start,$end,$reason,$hash){
   if(!$this->rows('SELECT merchant_id FROM merchant_organizations WHERE merchant_id=? AND active=1 FOR UPDATE',[$m]))throw new DomainException('Active synthetic merchant required.');$this->rows('INSERT INTO merchant_plan_heads(merchant_id) VALUES(?) ON DUPLICATE KEY UPDATE merchant_id=VALUES(merchant_id)',[$m]);$head=$this->rows('SELECT version FROM merchant_plan_heads WHERE merchant_id=? FOR UPDATE',[$m])[0];if($this->lifecycleEvent($m,true))throw new DomainException('Use lifecycle controls for this managed subscription.');$prior=$this->rows('SELECT * FROM merchant_plan_assignments WHERE request_id=? FOR UPDATE',[$request]);if($prior){$p=$prior[0];if($p['merchant_id']!==$m||$p['actor_id']!==$actor||!hash_equals($p['payload_hash'],$hash))throw new DomainException('Request key conflict.');return ['merchant'=>$m,'version'=>(int)$p['version']];}if((string)$head['version']!==$expected)throw new DomainException('Assignment changed; reload.');
   $p=$this->rows('SELECT * FROM merchant_plan_versions WHERE plan_id=? ORDER BY version DESC LIMIT 1 FOR UPDATE',[$plan]);if(!$p||!(int)$p[0]['active']||(string)$p[0]['version']!==$pv)throw new DomainException('Choose the latest active plan version.');$next=json_decode($p[0]['features_json'],true);$old=$this->assignment($m,true);$removed=array_diff($old?json_decode($old['features_json'],true):self::FEATURES,$next);if(array_intersect($removed,['pos','kitchen','floor','reservations'])&&$this->activeWork($m))throw new DomainException('Complete active services, occupied tables and bookings before removing operational modules, including scheduled removals.');
   $v=(int)$expected+1;$this->rows('INSERT INTO merchant_plan_assignments VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$m,$v,$plan,$pv,$start,$end,$actor,$request,$hash,$reason,$this->now()]);$this->rows('UPDATE merchant_plan_heads SET version=? WHERE merchant_id=?',[$v,$m]);return ['merchant'=>$m,'version'=>$v];});
 }
 private function activeWork(string $m):bool{
  if(PlatformAccess::enabled())return PlatformAccess::hasWork($this->db,$m);
  foreach(["SELECT COUNT(*) n FROM merchant_service_sessions WHERE merchant_id=? AND status IN ('DRAFT','SUBMITTED')","SELECT COUNT(*) n FROM merchant_seating_tables WHERE merchant_id=? AND operational_state IN ('OCCUPIED','RESERVED')","SELECT COUNT(*) n FROM merchant_seating_reservations WHERE merchant_id=? AND status IN ('REQUESTED','CONFIRMED','SEATED')"]as$sql)if((int)$this->rows($sql,[$m])[0]['n'])return true;return false;
 }
 /** Extra entitlement check; existing service/RBAC validation still executes and cannot be replaced by this grant. */
 public function requireFeature(string $m,string $o,string $feature,string $operation='new'):void{
  if(!self::enabled())return;if(!in_array($feature,self::FEATURES,true))throw new \LogicException('Unknown feature.');$this->scopedIdentity($m,$o);$a=$this->assignment($m,$this->db->inTransaction()&&!in_array($operation,['read','drain-read'],true));$state=$this->managedState($m);$licensed=$state?in_array($state['state'],['TRIAL','ACTIVE','GRACE'],true):($a&&(int)$a['expires_epoch']>$this->now());$licensed=$licensed&&PlatformAccess::canStart($this->db,$m,$o);$granted=$licensed&&in_array($feature,json_decode($a['features_json'],true),true)&&IntegratedSetup::permits($this->db,$m,$o,$feature,$operation);
  if(!$granted){if(in_array($feature,['pos','kitchen','floor','reservations'],true)&&in_array($operation,['drain','drain-read'],true)&&$this->activeWork($m))return;throw new DomainException('Module unavailable under the current demonstration plan. Open Subscription overview.');}
 }
 public function limit(string $m,string $o,string $kind):void{
  if(!self::enabled())return;if(!isset(self::LIMITS[$kind]))throw new \LogicException('Unknown quota.');$this->requireFeature($m,$o,['outlets'=>'multi_outlet','products'=>'menu','staff'=>'staff','tables'=>'floor'][$kind]);$a=$this->assignment($m,$this->db->inTransaction());$limits=json_decode($a['limits_json'],true);$count=match($kind){'outlets'=>$this->rows('SELECT COUNT(*) n FROM merchant_outlets WHERE merchant_id=?',[$m])[0]['n'],'products'=>$this->rows('SELECT COUNT(*) n FROM products p JOIN merchant_legacy_outlets l ON l.legacy_outlet_id=p.outlet_id WHERE l.merchant_id=?',[$m])[0]['n'],'tables'=>$this->rows('SELECT COUNT(*) n FROM merchant_seating_tables WHERE merchant_id=?',[$m])[0]['n'],'staff'=>$this->rows('SELECT COUNT(*) n FROM (SELECT user_id FROM merchant_memberships WHERE merchant_id=? UNION SELECT user_id FROM merchant_outlet_memberships WHERE merchant_id=?) x',[$m,$m])[0]['n']};if((int)$count>=(int)$limits[$kind])throw new DomainException('Demonstration plan limit reached; existing records remain intact.');
 }
 public function availability(string $m,string $o):array{$this->scopedIdentity($m,$o);$a=$this->assignment($m);$state=$this->managedState($m);$licensed=$state?in_array($state['state'],['TRIAL','ACTIVE','GRACE'],true):($a&&(int)$a['expires_epoch']>$this->now());$licensed=$licensed&&PlatformAccess::canStart($this->db,$m,$o);$f=$licensed?json_decode($a['features_json'],true):[];$f=array_values(array_filter($f,fn($feature)=>IntegratedSetup::permits($this->db,$m,$o,$feature,'read')));if($this->activeWork($m))$f=array_values(array_unique(array_merge($f,['pos','kitchen','floor','reservations'])));return $f;}
 public function platformLifecycleForTransaction(string $m):?array{
  if(!$this->db->inTransaction()||!PlatformAccess::enabled())throw new DomainException('Private native platform transaction required.');
  $actor=$this->auth->currentUserId();if(!$actor||!$this->rows("SELECT p.user_id FROM merchant_platform_memberships p JOIN merchant_staff s ON s.user_id=p.user_id AND s.active=1 JOIN merchant_role_permissions r ON r.role_code=p.role_code AND r.permission_code='manage_platform' WHERE p.user_id=? AND p.active=1 FOR UPDATE",[$actor]))throw new DomainException('Current platform authority required.');
  return $this->managedState($m,true);
 }
 public function platformOutletLimit(string $m):void{
  if(!$this->db->inTransaction()||!PlatformAccess::enabled())throw new DomainException('Platform outlet admission requires an enabled private transaction.');
  $actor=$this->auth->currentUserId();if(!$actor||!$this->rows("SELECT p.user_id FROM merchant_platform_memberships p JOIN merchant_staff s ON s.user_id=p.user_id AND s.active=1 JOIN merchant_role_permissions r ON r.role_code=p.role_code AND r.permission_code='manage_platform' WHERE p.user_id=? AND p.active=1 FOR UPDATE",[$actor]))throw new DomainException('Native platform permission required.');
  $state=$this->managedState($m,true);$a=$state['assignment']??$this->rawAssignment($m,true);$licensed=$state?in_array($state['state'],['TRIAL','ACTIVE','GRACE'],true):($a&&(int)$a['expires_epoch']>$this->now());
  if(!$licensed||!in_array('multi_outlet',json_decode($a['features_json'],true),true))throw new DomainException('Multi-outlet entitlement required.');
