 }
 public function platform():array{$this->admin();return ['versions'=>$this->rows('SELECT plan_id,version,name,description,active,features_json,limits_json,actor_id,created_epoch FROM merchant_plan_versions ORDER BY created_epoch DESC,version DESC LIMIT 200'),'plans'=>$this->rows('SELECT p.* FROM merchant_plan_versions p WHERE version=(SELECT MAX(x.version) FROM merchant_plan_versions x WHERE x.plan_id=p.plan_id) ORDER BY plan_id'),'merchants'=>$this->rows('SELECT m.merchant_id,m.name,COALESCE(h.version,0) version FROM merchant_organizations m LEFT JOIN merchant_plan_heads h ON h.merchant_id=m.merchant_id WHERE m.active=1 ORDER BY m.name'),'history'=>$this->rows('SELECT * FROM merchant_plan_assignments ORDER BY created_epoch DESC,version DESC LIMIT 200'),'lifecycle'=>self::lifecycleEnabled()?$this->lifecyclePlatform():null];}
 public function overview(string $m,string $o):array{$this->scopedIdentity($m,$o);$a=$this->assignment($m);$l=$this->managedState($m);return ['administrative'=>PlatformAccess::status($this->db,$m,$o),'lifecycle'=>$l,'lifecycleHistory'=>self::lifecycleEnabled()?$this->rows('SELECT version,action,from_status,to_status,reason,created_epoch FROM merchant_subscription_events WHERE merchant_id=? ORDER BY version DESC LIMIT 200',[$m]):[],'merchant'=>$m,'outlet'=>$o,'assignment'=>$a,'now'=>$this->now(),'state'=>$l?$l['state']:($a?((int)$a['expires_epoch']>$this->now()?'ACTIVE':'EXPIRED'):'UNASSIGNED / NOT YET EFFECTIVE'),'history'=>$this->rows('SELECT version,plan_id,plan_version,effective_epoch,expires_epoch,reason,created_epoch FROM merchant_plan_assignments WHERE merchant_id=? ORDER BY version DESC LIMIT 200',[$m]),'plans'=>$this->rows('SELECT p.plan_id,p.name,p.features_json,p.limits_json FROM merchant_plan_versions p WHERE p.active=1 AND p.version=(SELECT MAX(v.version) FROM merchant_plan_versions v WHERE v.plan_id=p.plan_id) ORDER BY plan_id')];}
